// Des: Command cars: parse pages to rows, roll up, retain
// Flo: dry-run counts what would be parsed > --live: pull, roll-up, purge in that order > export builds JSONL without raw phones
// I/O: Ctx (config, db) > one line or JSON, exit code; never touches the network
// ===================================================================
const std = @import("std"); const ctx3 = @import("ct-ctrl-ctxz.zig"); const pull = @import("ru-carz-pull.zig"); const roll = @import("ru-carz-roll.zig"); const purg = @import("ru-carz-purg.zig"); const snap = @import("sy-carz-snap.zig"); const pipe = @import("ru-page-fetc.zig"); const soc = @import("ct-ctrl-soci.zig");
const CF = .{ .dayz = 86400000, .part = ".part" };
const Outp = struct { iles: u32, ilin: u32, inew: u32, ibad: u32, seen: u32, pars: u32, skip: u32, lost: u32, news: u32, chan: u32, same: u32, gone: u32, grps: u32, pers: u32, text: u32, hist: u32, rows: u32 };
fn runzExpo(ctx2: *const ctx3.Ctxz) !u8 { var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); const body = try snap.rowsBuil(ctx2.allo, &dbzz); if (ctx2.args.outz.len == 0) { try std.Io.File.stdout().writeStreamingAll(ctx2.iozz, body); return 0; } const temp = try std.fmt.allocPrint(ctx2.allo, "{s}{s}", .{ ctx2.args.outz, CF.part }); const cwdz = std.Io.Dir.cwd(); var filz = try cwdz.createFile(ctx2.iozz, temp, .{}); filz.writeStreamingAll(ctx2.iozz, body) catch |err3| { filz.close(ctx2.iozz); return err3; }; filz.close(ctx2.iozz); try cwdz.rename(temp, cwdz, ctx2.args.outz, ctx2.iozz); try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "exported {d} car rows to {s}", .{ std.mem.count(u8, body, "\n"), ctx2.args.outz })); return 0; }
pub fn runzCarz(ctx2: *const ctx3.Ctxz) !u8 { if (!ctx3.dbzzHave(ctx2) and !(ctx2.conf.soci_enab and ctx2.args.live)) { try ctx3.outz(ctx2, "nothing to parse yet"); return 0; } if (std.mem.eql(u8, ctx2.args.urlz, "export")) return runzExpo(ctx2); if (!ctx2.conf.carz_enab) { try ctx3.outz(ctx2, "cars are off (carz_enab is false)"); return 0; } var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); const nowz = pipe.nowzMill(ctx2.iozz); const dryz = !ctx2.args.live; const conf = ctx2.conf;
    const ires = try soc.cronIngt(ctx2, &dbzz, dryz); const pres = try pull.pullRunz(&dbzz, ctx2.iozz, ctx2.dirz, conf, ctx2.init.gpa, nowz, dryz); const grps = try roll.rollRunz(&dbzz, ctx2.allo, nowz, @as(i64, conf.carz_stal_days) * CF.dayz, dryz); const cres = try purg.purgRunz(&dbzz, conf, nowz, dryz);
    const outp: Outp = .{ .iles = ires.file, .ilin = ires.line, .inew = ires.news + ires.chan, .ibad = ires.bads, .seen = pres.seen, .pars = pres.pars, .skip = pres.skip, .lost = pres.lost, .news = pres.news, .chan = pres.chan, .same = pres.same, .gone = pres.gone, .grps = grps, .pers = cres.pers, .text = cres.text, .hist = cres.hist, .rows = cres.rows }; const plai = try std.fmt.allocPrint(ctx2.allo, "cars {s} | social {d} file(s), {d} record(s), {d} new or changed, {d} bad | pages {d} seen, {d} to parse ({d} new, {d} changed, {d} same), {d} skipped, {d} lost | gone {d} | roll-up groups {d} | retention: phone {d}, text {d}, history {d}, rows {d}{s}", .{ if (dryz) "dry-run" else "live", outp.iles, outp.ilin, outp.inew, outp.ibad, outp.seen, outp.pars, outp.news, outp.chan, outp.same, outp.skip, outp.lost, outp.gone, outp.grps, outp.pers, outp.text, outp.hist, outp.rows, if (dryz) " | add --live to run" else "" }); try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, outp, plai)); return 0; }
